const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laSerena = ee.Geometry.Point([-71.2505, -29.9045]); // La Serena, Chile
  const yearToDateEnd = '2023-07-07';
  const yearToDateStart = '2023-01-01';

  const historicalStartYear = 1990;
  const historicalEndYear = 2020;

  const collectionId = 'UCSB-CHG/CHIRPS/DAILY';
  const bandName = 'precipitation';
  const scale = 5566; // CHIRPS original resolution is ~5.5km, so using this scale.

  // Helper function to get YTD rainfall for a given year
  const getYtdRainfall = async (year, geom, band, startDate, endDate) => {
    const col = ee.ImageCollection(collectionId)
      .filterDate(`${year}-${startDate}`, `${year}-${endDate}`)
      .filterBounds(geom);

    if (col.size().getInfo() === 0) {
      console.log(`No CHIRPS data for year ${year}.`);
      return null; // Indicate missing data for this year
    }

    // Sum all precipitation images in the collection for the period
    const totalPrecipitation = col.select(band).sum();

    // Reduce to get the value at the point
    const value = await totalPrecipitation.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    }).get(band).getInfo();

    return value;
  };

  try {
    // 2. Data Acquisition & Processing for Current Year (2023)
    const currentYearYtdRainfall = await getYtdRainfall(
      2023, laSerena, bandName, '01-01', '07-07'
    );

    if (currentYearYtdRainfall === null) {
      console.log("C1: No data for the current year's YTD period.");
      console.log("C1");
      return;
    }

    if (typeof currentYearYtdRainfall !== 'number' || isNaN(currentYearYtdRainfall)) {
      console.log("C3: Current year YTD rainfall calculation failed or returned invalid value.");
      console.log("C3");
      return;
    }


    // 3. Data Acquisition & Processing for Historical Average
    const historicalYtdRainfalls = [];
    for (let year = historicalStartYear; year <= historicalEndYear; year++) {
      const rainfall = await getYtdRainfall(
        year, laSerena, bandName, '01-01', '07-07'
      );
      if (rainfall !== null) { // Only include years with data
        historicalYtdRainfalls.push(rainfall);
      }
    }

    if (historicalYtdRainfalls.length === 0) {
      console.log("C1: No historical data available to calculate average.");
      console.log("C1");
      return;
    }

    const historicalAverageYtdRainfall = historicalYtdRainfalls.reduce((a, b) => a + b, 0) / historicalYtdRainfalls.length;

    if (isNaN(historicalAverageYtdRainfall) || historicalAverageYtdRainfall === null) {
      console.log("C3: Historical average rainfall calculation failed or returned invalid value.");
      console.log("C3");
      return;
    }

    // 4. Validation & Final Answer
    console.log(`2023 YTD Rainfall (Jan 1 - Jul 7): ${currentYearYtdRainfall.toFixed(2)} mm`);
    console.log(`1990-2020 Avg YTD Rainfall (Jan 1 - Jul 7): ${historicalAverageYtdRainfall.toFixed(2)} mm (based on ${historicalYtdRainfalls.length} valid years)`);

    if (currentYearYtdRainfall < historicalAverageYtdRainfall) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (e) {
    console.error("D: An error occurred during analysis:", e);
    console.log("D");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
